import { createContext, useContext, useMemo, useSyncExternalStore, type ReactNode } from 'react';
import en from './locales/en.json';
import de from './locales/de.json';
import fr from './locales/fr.json';
import it from './locales/it.json';
import {
  DEFAULT_SHELL_LOCALE,
  createTranslator,
  localizeText,
  mergeTranslations,
  normalizeLanguageTag,
  resolveShellLocale,
  subscribeHostLocale,
  type LocalizedText,
  type TranslationCatalog,
  type Translator,
} from './i18n-core.js';

/** Switzerland's official languages plus English: the catalogs the package ships. */
export const SHELL_LOCALES = ['de', 'fr', 'it', 'en'] as const;

const BUILT_IN_CATALOGS: Record<string, TranslationCatalog> = { en, de, fr, it };

/** `{ de: { toolbar: { add: 'Neu' } }, rm: { …a whole catalog… } }`: overrides or a new language. */
export type ShellTranslations = Record<string, TranslationCatalog>;

export interface ShellI18n {
  /** The resolved shell language (`de`, `fr`, `it`, `en`, or whatever a template passed). */
  locale: string;
  t: Translator;
  /** A `LocalizedText` label in the shell language. */
  localize: (value: LocalizedText | null | undefined) => string | undefined;
}

const ShellLocaleContext = createContext<ShellI18n | null>(null);

function supportedLocales(translations?: ShellTranslations | null): string[] {
  return [...SHELL_LOCALES, ...Object.keys(translations ?? {}).map((tag) => normalizeLanguageTag(tag) ?? tag)];
}

/**
 * The shell language a page resolves to without an explicit one: the host's declaration
 * (`uhuuData.locale` on a same-document host), `?lang=` / `?locale=`, `<html lang>`, then the
 * browser's preference list. `en` when nothing names a language, and always `en` without a window.
 */
export function detectShellLocale(translations?: ShellTranslations | null, explicit?: unknown): string {
  const supported = supportedLocales(translations);
  if (typeof window === 'undefined') return resolveShellLocale({ locale: explicit }, supported);
  const host = (window as any).uhuuData?.locale;
  return resolveShellLocale(
    {
      locale: explicit,
      host,
      search: window.location?.search,
      documentLang: window.document?.documentElement?.lang,
      navigatorLanguages: window.navigator?.languages ?? [window.navigator?.language],
    },
    supported,
  );
}

export function createShellI18n(locale: string, translations?: ShellTranslations | null): ShellI18n {
  const catalogs = mergeTranslations(BUILT_IN_CATALOGS, translations);
  const t = createTranslator({ locale, catalogs, fallbackLocale: DEFAULT_SHELL_LOCALE });
  return {
    locale,
    t,
    localize: (value) => localizeText(value, locale, DEFAULT_SHELL_LOCALE),
  };
}

/**
 * The language uhuu-app resolved for the user reaches a template frame once, in the host handshake
 * (`uhuuData.locale` in the `shaked` snapshot), which the SDK re-emits as its `loaded` event and does
 * not keep. Templates commonly render nothing until the payload arrives, which is after the
 * handshake, so a provider that subscribed on mount would miss it. The subscription therefore starts
 * when this module is evaluated: the SDK is a classic script in the template's <head>, so `$uhuu`
 * exists before the template bundle runs and before the handshake is answered.
 */
let hostLocale: string | null = null;
let hostSubscribed = false;
const hostLocaleListeners = new Set<() => void>();

function ensureHostSubscription() {
  if (hostSubscribed || typeof window === 'undefined') return;
  const uhuu = (window as any).$uhuu;
  if (typeof uhuu?.listen !== 'function') return;
  hostSubscribed = true;
  subscribeHostLocale(uhuu, (locale) => {
    if (locale === hostLocale) return;
    hostLocale = locale;
    hostLocaleListeners.forEach((listener) => listener());
  });
}

ensureHostSubscription();

function subscribeToHostLocale(listener: () => void) {
  ensureHostSubscription();
  hostLocaleListeners.add(listener);
  return () => {
    hostLocaleListeners.delete(listener);
  };
}

// Also the server snapshot: without a window there is no host, so it is null there anyway.
const getHostLocale = () => hostLocale;

function useHostLocale(): string | null {
  return useSyncExternalStore(subscribeToHostLocale, getHostLocale, getHostLocale);
}

let fallbackRuntime: { key: string | null; runtime: ShellI18n } | null = null;

/** What shell components use outside any provider (a lone `ImageBlock`): host language, else detected. */
function getFallbackRuntime(): ShellI18n {
  if (!fallbackRuntime || fallbackRuntime.key !== hostLocale) {
    fallbackRuntime = { key: hostLocale, runtime: createShellI18n(hostLocale ?? detectShellLocale()) };
  }
  return fallbackRuntime.runtime;
}

/** The shell runtime for a provider: explicit `locale`, else the host's, else detection. */
export function useShellI18nRuntime({
  locale,
  translations,
}: {
  locale?: string | null;
  translations?: ShellTranslations | null;
}): ShellI18n {
  const hostLocale = useHostLocale();
  const resolved = useMemo(
    () => normalizeLanguageTag(locale) ?? hostLocale ?? detectShellLocale(translations),
    [locale, hostLocale, translations],
  );
  return useMemo(() => createShellI18n(resolved, translations), [resolved, translations]);
}

export function ShellLocaleProvider({ value, children }: { value: ShellI18n; children: ReactNode }) {
  return <ShellLocaleContext.Provider value={value}>{children}</ShellLocaleContext.Provider>;
}

/** The shell's words and language. Falls back to a detected runtime outside a provider. */
export function useShellTranslation(): ShellI18n {
  const context = useContext(ShellLocaleContext);
  useHostLocale();
  return context ?? getFallbackRuntime();
}
