/**
 * The URL to render an image at, through the platform thumbnailer:
 *
 *   <img src={imageUrl(data.cover.image)} alt="" />   // ImageObject, URL string or nothing
 *   imageUrl(data.hero, { size: '1200x1200' })          // screen size override
 *
 * Print-aware size, encoded source, SVG and non-http sources passed through, an already
 * thumbnailed URL rebuilt rather than nested, `undefined` (no `src` attribute) for no image.
 * Each rule is a bug a template copy has shipped: docs/image-url.md. Pure: no React, no DOM.
 */
import { isPlainObject, textOf } from '../utility/json.js';

export const THUMBNAIL_ENDPOINT = 'https://render.uhuu.io/media/thumb';
export const SCREEN_SIZE = '2000x2000';
export const PRINT_SIZE = '4000x4000';

const SVG_TYPE = 'image/svg+xml';

function sourceOf(src) {
  if (typeof src === 'string') return { url: textOf(src) };
  if (!isPlainObject(src)) return { url: undefined };
  return {
    url: textOf(src.contentUrl) ?? textOf(src.url) ?? textOf(src.src),
    type: textOf(src.encodingFormat) ?? textOf(src.mimeType),
  };
}

function hostIsPrintProduct() {
  try {
    return Boolean(globalThis.$uhuu?.is?.printProduct?.());
  } catch {
    return false;
  }
}

function parse(url) {
  try {
    return new URL(url);
  } catch {
    return undefined;
  }
}

function isSvg(url, parsed, type) {
  if (type && type.toLowerCase().startsWith(SVG_TYPE)) return true;
  if (!parsed) return /\.svgz?(?:[?#]|$)/i.test(url);
  if (/\.svgz?$/i.test(parsed.pathname)) return true;
  for (const value of parsed.searchParams.values()) {
    const lower = value.toLowerCase();
    if (lower === 'svg' || lower === SVG_TYPE) return true;
  }
  return false;
}

const isThumbnail = (parsed) =>
  Boolean(parsed) && `${parsed.origin}${parsed.pathname}` === THUMBNAIL_ENDPOINT && parsed.searchParams.has('url');

/**
 * @param {string|{contentUrl?: string, url?: string, src?: string, encodingFormat?: string,
 *   mimeType?: string}|null|undefined} src
 * @param {{ print?: boolean, size?: string, printSize?: string, format?: string }} [options]
 * @returns {string|undefined}
 */
export function imageUrl(src, options = {}) {
  const settings = isPlainObject(options) ? options : {};
  const { url, type } = sourceOf(src);
  if (!url) return undefined;
  if (/^(?:data|blob):/i.test(url)) return url;

  let original = url;
  let parsed = parse(url);
  let format = textOf(settings.format);
  if (isThumbnail(parsed)) {
    if (!format) format = textOf(parsed.searchParams.get('format'));
    original = textOf(parsed.searchParams.get('url')) ?? url;
    parsed = parse(original);
  }

  if (!/^https?:\/\//i.test(original)) return original;
  if (isSvg(original, parsed, type)) return original;

  const print = typeof settings.print === 'boolean' ? settings.print : hostIsPrintProduct();
  const size = print ? (textOf(settings.printSize) ?? PRINT_SIZE) : (textOf(settings.size) ?? SCREEN_SIZE);
  const formatParam = format ? `&format=${encodeURIComponent(format)}` : '';
  return `${THUMBNAIL_ENDPOINT}?blank=true&size=${encodeURIComponent(size)}${formatParam}&url=${encodeURIComponent(original)}`;
}
